// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  AppWindowIcon,
  ArrowDownUpIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  ClipboardCheckIcon,
  CopyIcon,
  CopyXIcon,
  DownloadIcon,
  EllipsisVerticalIcon,
  GlobeIcon,
  LayersIcon,
  ListChecksIcon,
  ListIcon,
  MergeIcon,
  MoonIcon,
  PlusIcon,
  RefreshCwIcon,
  SearchIcon,
  SortAscIcon,
  Volume2Icon,
  XIcon,
  type LucideIcon,
} from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CLOSED,
  COPIED,
  COPY_FORMATS,
  DUPES,
  FILTERS,
  KEPT,
  MARKDOWN,
  MATCHES,
  PICKED_COPY,
  QUERY,
  SUMMARY,
  TABS,
  domainOf,
  pathOf,
} from './script'

const ROW = 26
const GAP = 3
const shown = { height: ROW, marginBottom: GAP, opacity: 1, borderWidth: 1 }
const gone = { height: 0, marginBottom: 0, opacity: 0, borderWidth: 0 }

const MENU: {
  label: string
  Icon?: LucideIcon
  d?: string
  sub?: boolean
  heading?: boolean
  off?: boolean
}[] = [
  { label: 'Open list of URLs…', Icon: PlusIcon },
  { label: 'Refresh', Icon: RefreshCwIcon },
  { label: 'Tidy up', heading: true },
  { label: `Close duplicates (${DUPES.size})`, Icon: CopyXIcon, d: 'close-dupes' },
  { label: 'Sleep all inactive tabs', Icon: MoonIcon },
  { label: 'Sort this window by website', Icon: SortAscIcon },
  { label: 'Merge all windows here', Icon: MergeIcon, off: true },
  { label: 'Copy shown tabs as', Icon: CopyIcon, d: 'copy-as', sub: true },
  { label: 'Export shown tabs', Icon: DownloadIcon, sub: true },
]

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const rows = (ids: number[]) => ids.map((id) => q(`row-${id}`))
  const menu = () => {
    move('more')
    click('more')
    tl.fromTo(
      q('menu'),
      { opacity: 0, y: -4, scale: 0.97 },
      { opacity: 1, y: 0, scale: 1, duration: 0.2, ease: 'power2.out', immediateRender: false },
      '<',
    )
  }

  step(0)
  move('search', { at: 0.2, ax: 0.3 })
  click('search')
  tl.to(q('search-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('search-text', QUERY, { speed: 0.07 })
  tl.to(
    rows(TABS.filter((tab) => !MATCHES.has(tab.id)).map((tab) => tab.id)),
    { ...gone, duration: 0.35, stagger: 0.03, ease: 'power2.inOut' },
    '<0.2',
  )
  tl.set(q('group-count'), { text: String(MATCHES.size) }, '<')
  move(`row-${[...MATCHES][0]}`, { at: '+=0.2', ax: 0.4 })

  step(1, '+=0.6')
  move('search-clear')
  click('search-clear')
  tl.set(q('search-text'), { text: '' }, '<')
  tl.to(q('search-ph'), { opacity: 1, duration: 0.1 }, '<')
  tl.to(qa('row'), { ...shown, duration: 0.35, ease: 'power2.inOut' }, '<')
  tl.set(q('group-count'), { text: String(TABS.length) }, '<')
  menu()
  move('close-dupes', { at: '+=0.1' })
  click('close-dupes')
  tl.to(q('menu'), { opacity: 0, duration: 0.15 }, '<0.1')
  tl.to(
    rows([...DUPES]),
    { backgroundColor: 'rgba(244,63,94,0.18)', borderColor: 'rgba(244,63,94,0.5)', duration: 0.15 },
    '<',
  )
  tl.to(rows([...DUPES]), { ...gone, duration: 0.35, stagger: 0.05, ease: 'power2.inOut' }, '>0.05')
  FILTERS.forEach((filter) => tl.set(q(`count-${filter.id}`), { text: String(filter.after) }, '<'))
  tl.set(q('group-count'), { text: String(KEPT.length) }, '<')
  tl.to(
    q('chip-duplicates'),
    {
      opacity: 0,
      width: 0,
      paddingLeft: 0,
      paddingRight: 0,
      marginLeft: -4,
      borderWidth: 0,
      duration: 0.3,
    },
    '<',
  )
  tl.to(q('summary'), { opacity: 0, duration: 0.15 }, '<')
  tl.set(q('notice-text'), { text: CLOSED }, '<')
  tl.fromTo(
    q('notice'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.25, immediateRender: false },
    '<0.1',
  )
  tl.to(q('undo'), { opacity: 1, duration: 0.1 }, '<')

  step(2, '+=0.8')
  menu()
  move('copy-as', { at: '+=0.1' })
  tl.to(q('copy-as'), { backgroundColor: 'var(--demo-tint-8)', duration: 0.1 }, '<0.2')
  tl.fromTo(
    q('submenu'),
    { opacity: 0, x: 4 },
    { opacity: 1, x: 0, duration: 0.2, immediateRender: false },
    '<',
  )
  move(`fmt-${PICKED_COPY}`)
  click(`fmt-${PICKED_COPY}`)
  tl.to([q('menu'), q('submenu')], { opacity: 0, duration: 0.15 }, '<0.1')
  tl.set(q('notice-text'), { text: COPIED }, '<')
  tl.to(q('undo'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('clip'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  cursorOut('+=0.4')
  final()
  wait(1.6)

  tl.set([q('menu'), q('submenu'), q('notice'), q('clip'), q('undo')], { opacity: 0 }, 0)
  tl.set([q('summary'), q('search-ph')], { opacity: 1 }, 0)
  tl.set(qa('row'), shown, 0)
  tl.set(q('search-text'), { text: '' }, 0)
  FILTERS.forEach((filter) => tl.set(q(`count-${filter.id}`), { text: String(filter.count) }, 0))
}

function Row({ tab }: { tab: (typeof TABS)[number] }) {
  const dupe = DUPES.has(tab.id)
  const path = pathOf(tab.url)
  return (
    <li
      data-d={`row row-${tab.id}`}
      className="relative flex items-center gap-1.5 overflow-hidden rounded-md border border-line bg-ink/[0.03] pl-1 pr-1"
      style={{ height: ROW, marginBottom: GAP }}
    >
      {tab.active ? (
        <span className="absolute inset-y-1.5 left-0 w-[2px] rounded-r-full bg-[var(--accent)]" />
      ) : null}
      <span className="flex size-5 shrink-0 items-center justify-center rounded bg-ink/[0.06]">
        <span
          className="flex size-3 items-center justify-center rounded-sm text-[7px] font-bold text-white"
          style={{ backgroundColor: tab.color }}
        >
          {domainOf(tab.url)[0].toUpperCase()}
        </span>
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[9.5px] font-medium leading-tight text-ink">
          {tab.title}
        </span>
        <span className="flex items-center gap-1 text-[8px] leading-tight text-muted">
          {tab.active ? (
            <span className="rounded bg-[var(--accent)]/15 px-0.5 text-[7px] text-[var(--accent)]">
              Active
            </span>
          ) : null}
          {tab.pinned ? (
            <span className="rounded bg-ink/10 px-0.5 text-[7px] text-ink-soft">Pinned</span>
          ) : null}
          {tab.audible ? <Volume2Icon className="size-2.5 text-emerald-300" /> : null}
          {dupe ? (
            <span className="rounded bg-amber-400/15 px-0.5 text-[7px] text-amber-300">Dup</span>
          ) : null}
          <span className="truncate">
            {domainOf(tab.url)}
            {path ? <span className="opacity-70">{path}</span> : null}
          </span>
        </span>
      </span>
      <EllipsisVerticalIcon className="size-3 shrink-0 text-muted" />
    </li>
  )
}

function Menus() {
  return (
    <>
      <div
        data-d="menu"
        className="absolute right-0 top-8 z-10 w-48 rounded-lg border border-line-strong bg-elevated p-1 text-[9.5px] text-ink-soft opacity-0 shadow-2xl"
      >
        {MENU.map(({ label, Icon, d, sub, heading, off }) =>
          heading ? (
            <span
              key={label}
              className="mt-1 block border-t border-line px-1.5 pb-0.5 pt-1 text-[8.5px] font-medium text-muted"
            >
              {label}
            </span>
          ) : (
            <span
              key={label}
              data-d={d}
              className={`flex items-center gap-1.5 rounded px-1.5 py-[3px] ${off ? 'opacity-40' : ''}`}
            >
              {Icon ? <Icon className="size-3 text-muted" /> : null}
              <span className="flex-1">{label}</span>
              {sub ? <ChevronRightIcon className="size-3 text-muted" /> : null}
            </span>
          ),
        )}
      </div>
      <div
        data-d="submenu"
        className="absolute right-[196px] top-[150px] z-10 w-32 rounded-lg border border-line-strong bg-elevated p-1 text-[9.5px] text-ink-soft opacity-0 shadow-2xl"
      >
        {COPY_FORMATS.map((label, index) => (
          <span key={label} data-d={`fmt-${index}`} className="block rounded px-1.5 py-[3px]">
            {label}
          </span>
        ))}
      </div>
      <div
        data-d="clip"
        className="absolute bottom-7 right-0 z-10 w-[300px] rounded-lg border border-line-strong bg-elevated p-2 opacity-0 shadow-2xl"
      >
        <p className="flex items-center gap-1.5 text-[9.5px] font-semibold text-ink">
          <ClipboardCheckIcon className="size-3 text-[var(--accent)]" /> Clipboard · Markdown links
        </p>
        <pre className="mt-1 overflow-hidden whitespace-pre rounded bg-ink/[0.04] p-1.5 font-mono text-[7.5px] leading-snug text-ink-soft">
          {MARKDOWN}
        </pre>
      </div>
    </>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Tab Manager searching ${TABS.length} tabs for "${QUERY}", closing ${DUPES.size} duplicates with undo, then copying the ${KEPT.length} that are left as Markdown links`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="relative flex h-full flex-col gap-1.5">
          <div className="flex items-center gap-1">
            <span
              data-d="search"
              className="relative flex h-6 flex-1 items-center gap-1.5 rounded-md border border-line-strong bg-canvas/80 px-2 text-[9.5px] text-ink"
            >
              <SearchIcon className="size-3 text-muted" />
              <span data-d="search-ph" className="absolute left-6 text-muted">
                Search tabs by title or URL…
              </span>
              <span data-d="search-text" />
              <XIcon data-d="search-clear" className="ml-auto size-3 text-muted" />
            </span>
            <span className="flex size-6 items-center justify-center text-muted">
              <ListChecksIcon className="size-3.5" />
            </span>
            <span data-d="more" className="flex size-6 items-center justify-center text-muted">
              <EllipsisVerticalIcon className="size-3.5" />
            </span>
          </div>
          <div className="flex gap-1">
            {FILTERS.map((filter, index) => (
              <span
                key={filter.id}
                data-d={`chip-${filter.id}`}
                className={`flex h-5 items-center gap-1 overflow-hidden whitespace-nowrap rounded-full border px-2 text-[8.5px] font-medium ${
                  index === 0
                    ? 'border-[var(--accent)]/40 bg-[var(--accent)]/10 text-[var(--accent)]'
                    : filter.id === 'duplicates'
                      ? 'border-line text-amber-300'
                      : 'border-line text-muted'
                }`}
              >
                {filter.label}
                <span
                  data-d={`count-${filter.id}`}
                  className="rounded-full bg-ink/10 px-1 text-[7.5px] tabular-nums"
                >
                  {filter.count}
                </span>
              </span>
            ))}
          </div>
          <div className="flex items-center justify-between">
            <span className="flex gap-0.5 rounded-md border border-line p-0.5 text-[8.5px]">
              {[
                { label: 'Window', Icon: LayersIcon },
                { label: 'Site', Icon: GlobeIcon },
                { label: 'List', Icon: ListIcon },
              ].map(({ label, Icon }, index) => (
                <span
                  key={label}
                  className={`flex items-center gap-1 rounded px-1.5 py-px ${index === 0 ? 'bg-ink/10 text-ink' : 'text-muted'}`}
                >
                  <Icon className="size-2.5" /> {label}
                </span>
              ))}
            </span>
            <span className="flex items-center gap-1 text-[8.5px] text-muted">
              <ArrowDownUpIcon className="size-2.5" /> Tab order
            </span>
          </div>
          <div className="min-h-0 flex-1 overflow-hidden">
            <p className="mb-1 flex items-center gap-1 text-[8.5px] font-semibold uppercase tracking-wide text-ink-soft">
              <ChevronDownIcon className="size-3 text-muted" />
              <AppWindowIcon className="size-3 text-muted" /> This window
              <span
                data-d="group-count"
                className="rounded-full bg-ink/10 px-1 text-[7.5px] font-normal tabular-nums text-muted"
              >
                {TABS.length}
              </span>
            </p>
            <ul>
              {TABS.map((tab) => (
                <Row key={tab.id} tab={tab} />
              ))}
            </ul>
          </div>
          <div className="relative h-5">
            <p
              data-d="summary"
              className="absolute inset-0 flex items-center text-[8.5px] tabular-nums text-muted"
            >
              {SUMMARY}
            </p>
            <div
              data-d="notice"
              className="absolute inset-0 flex items-center gap-2 rounded-md bg-ink px-2 text-[9px] text-canvas opacity-0"
            >
              <span data-d="notice-text" className="flex-1" />
              <span data-d="undo" className="font-semibold opacity-0">
                Undo
              </span>
            </div>
          </div>
          <Menus />
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
